package com.taylordproductivty.med_timing_tracker.data

import androidx.room.TypeConverter

enum class ProfileKind {
    PERSON,
    PET,
}

enum class DosingMode {
    INTERVAL,
    FIXED_SCHEDULE,
}

class Converters {
    @TypeConverter
    fun fromProfileKind(value: ProfileKind): String = value.name

    @TypeConverter
    fun toProfileKind(value: String): ProfileKind = ProfileKind.valueOf(value)

    @TypeConverter
    fun fromDosingMode(value: DosingMode): String = value.name

    @TypeConverter
    fun toDosingMode(value: String): DosingMode = DosingMode.valueOf(value)
}
